function inorderTraversal(root) {
  const result = [];

  function dfs(node) {
    if (!node) return;
    dfs(node.left);
    result.push(node.val);
    dfs(node.right);
  }

  dfs(root);
  return result;
}

// Iterative version using explicit stack:
function inorderIterative(root) {
  const result = [];
  const stack = [];
  let current = root;

  while (current || stack.length) {
    while (current) {
      stack.push(current);
      current = current.left;
    }
    current = stack.pop();
    result.push(current.val);
    current = current.right;
  }
  return result;
}

function preorderTraversal(root) {
  const result = [];

  function dfs(node) {
    if (!node) return;
    result.push(node.val); // root
    dfs(node.left);        // left
    dfs(node.right);       // right
  }

  dfs(root);
  return result;
}

// Iterative version:
function preorderIterative(root) {
  if (!root) return [];
  const result = [];
  const stack = [root];

  while (stack.length) {
    const node = stack.pop();
    result.push(node.val);
    // Push right first so left is processed first
    if (node.right) stack.push(node.right);
    if (node.left) stack.push(node.left);
  }
  return result;
}

function isValidBST(root) {
  function validate(node, min, max) {
    if (!node) return true;

    // Current node must be within bounds
    if (min !== null && node.val <= min) return false;
    if (max !== null && node.val >= max) return false;

    // Left subtree: max bound = current node value
    // Right subtree: min bound = current node value
    return (
      validate(node.left, min, node.val) &&
      validate(node.right, node.val, max)
    );
  }

  return validate(root, null, null);
}

function isValidBSTInOrder(root) {
  let prev = null;

  function inOrder(node) {
    if (!node) return true;

    if (!inOrder(node.left)) return false;

    // Current value must be greater than previous
    if (prev !== null && node.val <= prev) return false;
    prev = node.val;

    return inOrder(node.right);
  }

  return inOrder(root);
}

// Also works: check if in-order traversal produces sorted array

function lowestCommonAncestorBST(root, p, q) {
  let current = root;

  while (current) {
    // Both p and q are in right subtree
    if (p.val > current.val && q.val > current.val) {
      current = current.right;
    }
    // Both p and q are in left subtree
    else if (p.val < current.val && q.val < current.val) {
      current = current.left;
    }
    // Current node is the split point — this is LCA
    else {
      return current;
    }
  }
  return null;
}

// Usage: LCA of 2 and 8 in BST [6,2,8,0,4,7,9] = 6

function lowestCommonAncestor(root, p, q) {
  if (!root || root === p || root === q) return root;

  const left = lowestCommonAncestor(root.left, p, q);
  const right = lowestCommonAncestor(root.right, p, q);

  // If both sides return non-null, current is LCA
  if (left && right) return root;
  // Otherwise return the non-null side
  return left || right;
}

// Example tree: [3,5,1,6,2,0,8,null,null,7,4]
// LCA(5, 1) = 3, LCA(5, 4) = 5

function maxDepth(root) {
  if (!root) return 0;

  const leftDepth = maxDepth(root.left);
  const rightDepth = maxDepth(root.right);

  return Math.max(leftDepth, rightDepth) + 1;
}

// BFS alternative (level-order):
function maxDepthBFS(root) {
  if (!root) return 0;
  let depth = 0;
  const queue = [root];

  while (queue.length) {
    depth++;
    const levelSize = queue.length;
    for (let i = 0; i < levelSize; i++) {
      const node = queue.shift();
      if (node.left) queue.push(node.left);
      if (node.right) queue.push(node.right);
    }
  }
  return depth;
}

function diameterOfBinaryTree(root) {
  let maxDiameter = 0;

  function height(node) {
    if (!node) return 0;

    const leftHeight = height(node.left);
    const rightHeight = height(node.right);

    // Diameter through current node
    const diameter = leftHeight + rightHeight;
    maxDiameter = Math.max(maxDiameter, diameter);

    // Return height for parent's calculation
    return Math.max(leftHeight, rightHeight) + 1;
  }

  height(root);
  return maxDiameter;
}

// Usage: diameterOfBinaryTree([1,2,3,4,5]) = 3 (path 4-2-1-3)

function invertTree(root) {
  if (!root) return null;

  // Swap left and right subtrees
  const temp = root.left;
  root.left = root.right;
  root.right = temp;

  // Recursively invert subtrees
  invertTree(root.left);
  invertTree(root.right);

  return root;
}

// One-liner:
function invertTreeShort(root) {
  if (!root) return null;
  [root.left, root.right] = [invertTree(root.right), invertTree(root.left)];
  return root;
}

function invertTreeIterative(root) {
  if (!root) return null;
  const queue = [root];

  while (queue.length) {
    const node = queue.shift();

    // Swap children
    [node.left, node.right] = [node.right, node.left];

    if (node.left) queue.push(node.left);
    if (node.right) queue.push(node.right);
  }

  return root;
}

// Iterative DFS alternative:
function invertTreeDFS(root) {
  if (!root) return null;
  const stack = [root];

  while (stack.length) {
    const node = stack.pop();
    [node.left, node.right] = [node.right, node.left];
    if (node.left) stack.push(node.left);
    if (node.right) stack.push(node.right);
  }
  return root;
}
